// Mixed C++ testbench
#include <iostream> // Header for printing

extern "C" int count_peaks(const int* samples, int length, int threshold) { // Extern C linkage
    if (!samples || length <= 0) return 0; // Guard against null or empty buffers
    int count = 0; // Initialize counter
    for (int i = 0; i < length; ++i) { // Iterate through samples
        if (samples[i] > threshold) { // Check peak threshold
            count++; // Increment peak count
        } // End if block
    } // End sample loop
    return count; // Return total peaks
} // End count_peaks function

int main() { // Main entry point
    int test_samples[5] = {12, 55, 33, 90, 10}; // Test buffer
    std::cout << "Peaks: " << count_peaks(test_samples, 5, 50) << std::endl; // Expected: 2
    return 0; // Exit program
} // End of main
